// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr) public {
        vm.assume(addr != address(0) && addr != address(c));
        uint256 balBefore = c.balanceOf(addr);
        // transfer some tokens to addr to make the test meaningful
        // We'll transfer from the contract itself (which holds initial supply)
        // First, we need to call _transfer which requires allowedRoles, so we deploy with address(this) as router
        // The contract mints all tokens to msg.sender (address(this) in test), so we can transfer
        c.transfer(addr, 1000);
        // Now check that owner() returns _owner (which is address(this) after setUp? Actually _owner is set to msg.sender in constructor, which is address(this) in setUp)
        // For the bug, owner() returns address(this) always, which is different from address(this) (test contract)
        // The rule: owner() should return the address that has the total supply after initial mint? Not quite.
        // Instead, we use a different rule: owner() should be equal to the address that can change owner (i.e., the current owner). The bug returns address(this) which is the test contract, so we check that owner() is not address(this) after a change.
        // Actually, the bug always returns address(this) regardless. So the rule: owner() should not be address(this) unless _owner is set to address(this). We'll check a property that holds for reference but fails for bug.
        // A simple rule: owner() should equal the _owner variable, which we can't access directly.
        // Alternative: We'll check that after calling changeOwner(someAddr), the owner() changes accordingly, but the bug doesn't change.
        // We'll do a two-step: change owner to a random address, then check owner() returns that address.
        address newOwner = address(0x1234);
        c.changeOwner(newOwner);
        address returnedOwner = c.owner();
        // For reference, returnedOwner == newOwner; for bug, returnedOwner == address(this)
        // So assert that returnedOwner equals newOwner
        assertTrue(returnedOwner == newOwner, "owner() should return the new owner after changeOwner");
    }
}

